select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_SAP_STORE_CALENDAR','RRL_SAP_STORE_ORDER','RRL_SAP_STORE_MESSAGE','RRL_SAP_STORE_PICK_GUARD','RRL_SAP_STORE_ROW_GUARD','RRL_SAP_STORE_HEAD_GUARD') order by OBJECT_NAME;
select NAME,LINE,TEXT from USER_ERRORS where NAME in('RRL_SAP_STORE_PICK_GUARD','RRL_SAP_STORE_ROW_GUARD','RRL_SAP_STORE_HEAD_GUARD');
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-07-008-ni02-store-orders';